// Scale the grid (change the 5.0 to shrink/enlarge)
vec3 p = pModel * 5.0;

// Compute the line thickness
vec3 grid = abs(fract(p - 0.5) - 0.5) / fwidth(p);
float line = min(min(grid.x, grid.y), grid.z);
float colorIntensity = 1.0 - min(line, 1.0);

// Background = u_col2, neon lines = u_col1 (dock colors)
textureCol = mix(ubuf.u_col2, ubuf.u_col1, colorIntensity);
